/* Contenido de «IA para Agronegocios y Campo». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-ia-campo",{"l":{"c-ia-campo-m1-l1":[{"tipo":"texto","texto":"Casi toda la información del campo vive en la cabeza del productor: cuándo se sembró, qué se aplicó, cuánto se pagó de jornales, qué lote salió mejor. El problema aparece al año siguiente, cuando hay que decidir y nadie se acuerda de los números. La IA no siembra, pero sí convierte tus notas de voz al pie del surco en una bitácora que puedes consultar y comparar entre ciclos."},{"tipo":"plantilla","rotulo":"De nota de voz a bitácora","texto":"Estas son mis notas del día en la parcela, tal como las dicté [pega la transcripción]. Ordénalas en un registro con este formato: fecha; lote o sección; labor realizada (preparación, siembra, riego, fertilización, control de maleza, monitoreo, cosecha); superficie trabajada en hectáreas; personal (cuántos y a qué pago); insumo usado con cantidad y unidad; maquinaria y horas; clima del día; y observaciones. Usa solo lo que está en mis notas; lo que no mencione, déjalo en blanco, no lo completes. Al final dime qué datos me faltaron para que mañana los registre."},{"tipo":"tabla","titulo":"Los cinco datos que sí o sí se registran","encabezados":["Dato","Por qué importa después"],"filas":[["Fecha de la labor","Permite comparar ciclos y calcular días entre labores"],["Lote y hectáreas","Sin superficie no hay costo ni rendimiento por hectárea"],["Cantidad exacta de insumo","Es la partida más cara y la que más se descontrola"],["Jornales y pago","Segundo costo más grande de casi todo cultivo"],["Lo que observaste en la planta","Es lo que después explica por qué un lote rindió más"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Registras «se aplicó fertilizante» sin cantidad ni lote.","ops":["Ese registro no sirve para calcular nada","Está bien, lo importante es que quedó anotado","Sirve si al final del ciclo sumas las facturas"],"correcta":0},{"p":"La IA llenó en la bitácora una cantidad que tú no dictaste.","ops":["La borro y la dejo en blanco hasta confirmarla","La dejo, se ve lógica","La cambio por la dosis que venía en el costal"],"correcta":0},{"p":"La mejor forma de registrar en plena jornada es…","ops":["Nota de voz en el momento y ordenar en la noche","De memoria al final de la semana","Pedirle al comprador que lleve la cuenta"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la frase","instruccion":"Escribe la palabra que falta. Puedes usar la abreviatura.","items":[{"frase":"La superficie de un lote se mide en ___.","resp":["hectáreas","hectareas","hectárea","ha"],"pista":"Una de ellas son 10,000 metros cuadrados."},{"frase":"Para comparar dos lotes de distinto tamaño se calcula el rendimiento por ___.","resp":["hectárea","hectarea","hectáreas","ha"],"pista":"Producción total dividida entre la superficie."},{"frase":"Un registro de aplicación sin la ___ usada no sirve para sacar costos.","resp":["cantidad","dosis","cantidad exacta"],"pista":"Es el número que va junto a la unidad."}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> el encargado de una huerta de aguacate en Uruapan te manda notas de voz. En una dice: «Mañana toca el fungicida en la huerta 2, ya está el producto en la bodega». La bitácora que armó la IA registra: «Hoy: aplicación de fungicida en huerta 2». Al día siguiente llovió y la aplicación no se hizo."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuál fue el error de la IA?","ops":["Convertir una labor planeada en una labor realizada","Usar el nombre de la huerta","Anotar la fecha"],"correcta":0,"explica":"Plan y hecho son registros distintos; mezclarlos arruina el historial de aplicaciones."},{"p":"¿Por qué importa tanto en una aplicación?","ops":["No importa","Porque el historial de aplicaciones define intervalos antes de cosechar y lo revisan compradores y auditores","Solo por orden"],"correcta":1,"explica":"Una aplicación registrada que no ocurrió, o al revés, puede llevar a cosechar en un momento equivocado."},{"p":"¿Qué instrucción agregas al prompt?","ops":["«Resume todo en una línea»","«Completa lo que falte»","«Separa en dos listas: labores realizadas hoy y labores planeadas; si hay duda, pregúntame»"],"correcta":2,"explica":"Separar plan y hecho, y pedir que pregunte en la duda, evita el error."}]},{"tipo":"completar","rotulo":"Bitácora fiel","items":[{"frase":"«Mañana toca» es una labor ___, no realizada.","resp":["planeada","programada","pendiente"]},{"frase":"Si hay duda, la IA debe ___ antes de registrar.","resp":["preguntar","preguntarme"]},{"frase":"Una aplicación se registra cuando ya se ___.","resp":["hizo","aplicó","aplico","realizó","realizo"]}]},{"tipo":"clave","items":["Nota de voz en el momento; la IA ordena en la noche.","Fecha, lote, hectáreas, insumo con cantidad y jornales.","Lo que no dictaste se queda en blanco, no se inventa."]}],"c-ia-campo-m1-l2":[{"tipo":"texto","texto":"Los insumos son la partida que más se desangra: se compra de más, se guarda mal, se aplica sin anotar y a fin de ciclo nadie sabe cuánto se gastó ni en qué lote. Un control de insumos bien llevado te dice tres cosas: cuánto tienes, cuánto aplicaste por hectárea y cuánto te costó."},{"tipo":"plantilla","rotulo":"Registro de aplicación","texto":"Diséñame un formato de registro de aplicaciones que pueda llenar desde el celular, con estas columnas: fecha, lote, hectáreas tratadas, producto tal como viene en la etiqueta, dosis aplicada con su unidad, volumen de agua, equipo utilizado, quién aplicó, condiciones del clima al momento, y observaciones. Agrega una hoja de bodega con entradas y salidas para saber la existencia de cada producto. Dame también una lista de las preguntas que debo hacerle a mi técnico antes de cada aplicación. No me sugieras productos ni dosis."},{"tipo":"destacado","texto":"<b>Aquí la IA no opina.</b> Qué producto usar, en qué dosis, con qué intervalo antes de cosechar y qué medidas de protección tomar es información que viene en la <b>etiqueta del producto</b> y que confirma un técnico o ingeniero agrónomo con responsiva. Si le pides una receta a un chat, te va a dar algo que suena convincente y puede dañar el cultivo, a quien aplica, o dejar residuos que te rechacen la venta. Usa la IA para <b>registrar y ordenar</b>, nunca para recetar."},{"tipo":"relacionar","rotulo":"Dato de la aplicación y para qué te sirve","pares":[["Fecha y lote","Saber el intervalo real entre aplicaciones"],["Hectáreas tratadas","Calcular cuánto producto te rinde por hectárea"],["Dosis y volumen de agua","Repetir la aplicación que sí funcionó"],["Quién aplicó y con qué equipo","Ubicar fallas de calibración o de manejo"],["Clima al momento","Explicar por qué una aplicación no dio resultado"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Le pides a la IA qué producto aplicar contra una plaga.","ops":["No es su trabajo: eso lo define un técnico y la etiqueta","Es útil, siempre que suene razonable","Sirve si luego lo compras en la tienda de siempre"],"correcta":0},{"p":"Tienes 40 litros de un producto en bodega y aplicaste 12 sin anotar.","ops":["El control de existencias ya no cuadra y hay que ajustarlo con conteo físico","No importa, se nota al final","Compras 12 litros más para reponer sin contar"],"correcta":0},{"p":"Registrar las hectáreas tratadas sirve para…","ops":["Saber tu consumo de insumo por hectárea","Nada en particular","Cumplir con el comprador, nada más"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de tomate en Sinaloa le preguntó a un asistente de IA la dosis de un insecticida. La IA contestó con una dosis por hectárea y «intervalo de seguridad de 3 días». Al revisar la etiqueta, el producto ni siquiera tiene al tomate entre sus cultivos autorizados."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué manda sobre dosis, cultivos e intervalo de seguridad?","ops":["La respuesta de la IA","La etiqueta autorizada del producto y la recomendación del agrónomo","Lo que usa el vecino"],"correcta":1,"explica":"La etiqueta indica cultivos, dosis, intervalo antes de cosecha, reentrada y protección; el agrónomo la aplica a tu caso."},{"p":"Si el cultivo no aparece en la etiqueta…","ops":["No se usa ese producto en ese cultivo; se consulta alternativa con el agrónomo","Se usa a media dosis","Se usa si la IA lo recomienda"],"correcta":0,"explica":"Usarlo fuera de etiqueta puede dejar residuos no permitidos y hacer que rechacen la cosecha."},{"p":"¿Para qué sí sirve la IA con agroquímicos?","ops":["Para recetar","Para calcular la dosis","Para armar tu registro de aplicaciones y la lista de preguntas para el agrónomo"],"correcta":2,"explica":"Registrar y preguntar bien, sí; recetar, nunca."}]},{"tipo":"comparar","titulo":"Pregunta a la IA sobre una plaga","malTitulo":"Peligrosa","mal":"«¿Qué dosis de este insecticida le pongo al tomate?»","bienTitulo":"Útil","bien":"«Ayúdame a preparar la consulta para mi agrónomo: cultivo, etapa, plaga observada, % de plantas afectadas, aplicaciones previas con fecha y días que faltan para cosechar.»"},{"tipo":"reflexion","rotulo":"Tu lectura de etiqueta","pregunta":"Toma la etiqueta de un producto que uses y escribe dónde vienen: cultivos autorizados, dosis, intervalo de seguridad, reentrada y equipo de protección.","ayuda":"Producto: … / Cultivos: … / Intervalo: … / Reentrada: … / Equipo: …"},{"tipo":"clave","items":["Cada aplicación: fecha, lote, hectáreas, producto, dosis y quién aplicó.","Bodega con entradas, salidas y conteo físico.","La receta la da el técnico y la etiqueta, no la IA."]}],"c-ia-campo-m1-l3":[{"tipo":"texto","texto":"Si no sabes tu costo por hectárea, no sabes a qué precio te conviene vender ni si en realidad ganaste. Es una cuenta sencilla: todo lo que gastaste en el ciclo, dividido entre las hectáreas que trabajaste. Lo difícil no es la división: es acordarse de meter todo, incluido tu propio trabajo."},{"tipo":"excel","rotulo":"Tu costo por hectárea","datos":[["Concepto","Costo del ciclo ($)"],["Preparación de terreno",9800],["Semilla",12500],["Fertilizante",31000],["Riego y energía",7400],["Jornales",18600],["Costo total",""],["Hectáreas trabajadas",6],["Costo por hectárea",""],["% que pesa el fertilizante",""]],"retos":[{"celda":"B7","formula":"=SUMA(B2:B6)","esperado":79300,"requiere":"SUMA(","texto":"<b>B7</b>: costo total del ciclo."},{"celda":"B9","formula":"=B7/B8","esperado":13216.666666666666,"texto":"<b>B9</b>: costo por hectárea = costo total ÷ hectáreas."},{"celda":"B10","formula":"=B4/B7","esperado":0.39092055485498106,"texto":"<b>B10</b>: qué parte del costo se va en fertilizante.","explica":"$13,216 por hectárea, y el 39% del gasto está en un solo insumo. Ese es el primer lugar donde conviene comparar proveedores, revisar la dosis con tu técnico o negociar compra en conjunto con otros productores."}]},{"tipo":"plantilla","rotulo":"Revisar que no falte nada","texto":"Estoy calculando mi costo por hectárea de [cultivo] en [superficie] hectáreas. Estos son los gastos que ya tengo anotados: [pega tu lista con montos]. Revísala y dime qué tipos de costo suelen olvidarse en este tipo de producción: renta o valor de la tierra, mano de obra familiar, maquinaria propia y su mantenimiento, combustible, transporte, empaque, acarreos, intereses de crédito, seguros, mermas y tu propio tiempo de administración. Preséntalo como lista de preguntas para que yo las conteste con mis números. No inventes montos."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Trabajas tú y tu familia todo el ciclo y no se anota ningún jornal.","ops":["El costo por hectárea sale falsamente bajo","Está bien, no se paga nada","El costo sale alto porque la familia gasta más"],"correcta":0},{"p":"Costo por hectárea =","ops":["Costo total del ciclo ÷ hectáreas trabajadas","Hectáreas ÷ costo total","Costo total × hectáreas"],"correcta":0},{"p":"Un insumo que pesa el 39% de tu costo…","ops":["Es donde más te conviene negociar y revisar dosis","Da igual, ya está comprado","Se sustituye por el más barato sin consultar"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu parcela","pregunta":"Escribe de memoria tus tres gastos más grandes del último ciclo y cuántas hectáreas trabajaste. Con eso ya puedes empezar tu hoja de costos.","ayuda":"Gasto 1… / Gasto 2… / Gasto 3… / Hectáreas…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de maíz de temporal en los Altos de Jalisco pidió a la IA completar su hoja de costos. La IA agregó una renta de tierra «promedio en Jalisco» que no sabe de dónde salió, y no incluyó los intereses del crédito de avío con el que compró la semilla y el fertilizante."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"La renta «promedio en Jalisco»…","ops":["Se usa, es un promedio","Se sustituye por lo que pagas o lo que te pagarían por rentar tu tierra en tu zona","Se elimina del costo"],"correcta":1,"explica":"La renta es de tu zona y tu tierra; si es propia, se usa lo que te pagarían por rentarla."},{"p":"Los intereses del crédito de avío…","ops":["Se agregan como costo del ciclo con los datos de tu contrato","No son costo de producción","Los paga el gobierno"],"correcta":0,"explica":"El dinero prestado cuesta; si no lo cuentas, el costo por hectárea sale bajo."},{"p":"¿Qué le pides a la IA al completar costos?","ops":["Que ponga cifras promedio","Que calcule tu ganancia","Que te pregunte por cada tipo de costo sin inventar montos"],"correcta":2,"explica":"La IA te ayuda a no olvidar; los números son tuyos."}]},{"tipo":"completar","rotulo":"Costos completos","items":[{"frase":"Si la tierra es propia, se usa lo que te pagarían por ___.","resp":["rentarla","renta"]},{"frase":"Los intereses del crédito son un ___ del ciclo.","resp":["costo","gasto"]},{"frase":"Los montos de la hoja de costos salen de tus ___.","resp":["registros","notas","facturas"]}]},{"tipo":"clave","items":["Costo por hectárea = costo total ÷ hectáreas.","Incluye tu trabajo, la maquinaria propia y la renta de la tierra.","El insumo que más pesa es el primero que se negocia."]}],"c-ia-campo-m2-l1":[{"tipo":"texto","texto":"Sembrar, aplicar, regar o cosechar en el día equivocado cuesta dinero y a veces cuesta el ciclo entero. El pronóstico lo consultas en el servicio meteorológico y en las estaciones de tu región; lo que la IA hace bien es lo de después: ordenar el plan de la semana, repartir la cuadrilla y redactar los avisos."},{"tipo":"destacado","texto":"<b>La IA de texto no sabe qué clima va a hacer.</b> No tiene el pronóstico de hoy ni de tu municipio; si se lo preguntas, te puede dar una respuesta inventada con toda seguridad. Consulta el pronóstico en la fuente oficial y en tu estación más cercana, y <b>pégaselo</b> a la IA para que te ayude a decidir qué mover."},{"tipo":"plantilla","rotulo":"Plan de la semana con el pronóstico pegado","texto":"Este es el pronóstico de mi zona para los próximos 7 días, copiado de la fuente oficial: [pega temperatura, probabilidad de lluvia, viento y humedad por día]. Tengo pendientes estas labores: [lista con lote, hectáreas y cuántos días de trabajo necesita cada una]. Cuento con [número] trabajadores y [maquinaria disponible]. Ayúdame a acomodar la semana: qué día conviene cada labor según las condiciones, cuáles no se deben hacer con lluvia o viento, qué dejo de respaldo por si cambia el clima y qué labores puedo adelantar. Explícame el porqué de cada decisión para que yo la valide con lo que veo en campo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Le preguntas a la IA si va a llover el jueves en tu municipio.","ops":["No lo sabe: consulto el pronóstico oficial","Me fío de lo que conteste","Le pregunto dos veces y me quedo con la respuesta repetida"],"correcta":0},{"p":"Pegarle el pronóstico a la IA sirve para…","ops":["Que te ayude a acomodar las labores de la semana","Que te diga el clima real","Que el pronóstico sea más exacto"],"correcta":0},{"p":"El plan de la semana que te devuelve la IA…","ops":["Lo validas con lo que ves en tu parcela","Se ejecuta tal cual","Se manda a la cuadrilla sin revisar"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena cómo se decide una labor","items":[{"frase":"consultar pronóstico revisar parcela acomodar labores avisar cuadrilla registrar bitácora","es":"Del pronóstico oficial al registro del día"}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de sorgo en Tamaulipas le pregunta a la IA: «¿Puedo aplicar herbicida mañana?». La IA contesta: «Sí, las condiciones son ideales». No le dio ningún pronóstico y el servicio meteorológico anuncia rachas de viento fuertes para mañana en su zona."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"La respuesta «condiciones ideales»…","ops":["Es confiable","Es inventada: la IA no tenía el pronóstico","Es confiable si es de mañana"],"correcta":1,"explica":"Sin datos pegados, la IA contesta lo que suena bien."},{"p":"Con viento fuerte, una aplicación…","ops":["Se reprograma: el producto puede derivar a otros cultivos, casas o cuerpos de agua","Se hace temprano sin revisar","Se hace con más producto"],"correcta":0,"explica":"La etiqueta y el técnico indican las condiciones de aplicación; con viento se pierde producto y se daña lo de al lado."},{"p":"¿Cómo debió preguntar?","ops":["Igual, pero dos veces","Pidiendo a otra IA","Pegando el pronóstico oficial y las condiciones de la etiqueta, y pidiendo el mejor día de la semana"],"correcta":2,"explica":"Con datos reales, la IA ayuda a acomodar; tú decides."}]},{"tipo":"relacionar","rotulo":"Dato y dónde lo consultas","pares":[["Pronóstico de lluvia y viento","Servicio meteorológico oficial y estación cercana"],["Condiciones para aplicar","Etiqueta del producto y técnico"],["Estado del cultivo","Tu recorrido en campo"],["Plan de la semana","La IA con los datos que tú le pegas"]]},{"tipo":"clave","items":["El pronóstico sale de la fuente oficial, no de la IA.","Pega el pronóstico y deja que la IA acomode la semana.","Siempre una labor de respaldo por si cambia el clima."]}],"c-ia-campo-m2-l2":[{"tipo":"texto","texto":"Cuando aparece un problema en el cultivo, lo que decide la respuesta correcta es una buena descripción: qué parte de la planta está afectada, desde cuándo, en qué parte del lote, qué tan rápido avanza y qué se aplicó antes. Ese reporte bien hecho es lo que le ahorra tiempo a tu técnico. La IA te ayuda a armarlo y a no olvidar nada; el diagnóstico no es suyo."},{"tipo":"plantilla","rotulo":"Reporte de monitoreo para tu técnico","texto":"Ayúdame a armar un reporte de lo que estoy viendo en mi cultivo de [cultivo], etapa [etapa del cultivo], en [superficie] hectáreas. Hazme las preguntas una por una para no dejar nada fuera: parte de la planta afectada, cómo se ve el daño, desde cuándo, cómo se distribuye en el lote (manchones, orilla, parejo), porcentaje aproximado de plantas afectadas, si avanza y a qué velocidad, clima de los últimos días, riegos y aplicaciones recientes con fecha, y qué diferencia hay con los lotes sanos. Al terminar, ordénalo en un reporte breve que le voy a mandar a mi técnico junto con fotos. No propongas diagnóstico ni producto."},{"tipo":"destacado","texto":"<b>Un diagnóstico por chat puede costarte el ciclo.</b> Síntomas parecidos pueden venir de plaga, enfermedad, falta de un nutriente, exceso de agua o daño por aplicación previa, y el manejo de cada caso es distinto. La IA no ve tu planta, no conoce tu suelo y no se hace responsable. Quien diagnostica y firma la recomendación es un ingeniero agrónomo o el técnico que atiende tu zona."},{"tipo":"relacionar","rotulo":"Lo que observas y por qué se anota","pares":[["Distribución en manchones o en la orilla","Orienta sobre cómo se está moviendo el problema"],["Porcentaje de plantas afectadas","Permite medir si avanza o se detuvo"],["Fecha de la última aplicación","Descarta o confirma daño por el manejo previo"],["Riegos y lluvias recientes","Muchos problemas se disparan con exceso de humedad"],["Cómo se ve un lote sano al lado","Sirve de comparación para el técnico"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA te dice con seguridad qué enfermedad es y qué aplicar.","ops":["No lo tomo como diagnóstico: lo consulto con el técnico","Aplico lo que dijo","Aplico la mitad de la dosis por si acaso"],"correcta":0},{"p":"Lo más útil que puedes mandarle a tu técnico es…","ops":["Fotos y una descripción completa con fechas","Un mensaje diciendo que las plantas están mal","El nombre del producto que sugirió la IA"],"correcta":0},{"p":"Anotar el porcentaje de plantas afectadas sirve para…","ops":["Saber después si el problema avanzó o se detuvo","Llenar el formato","Pedir un descuento al proveedor de semilla"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de chile en Zacatecas subió la foto de una hoja amarillenta a una aplicación con IA. La respuesta: «Es un virus; arranca las plantas afectadas y aplica este producto a todo el lote». El técnico de la zona no ha visitado la parcela."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué haces con el «diagnóstico» de la aplicación?","ops":["Lo tomas como una posibilidad y armas el reporte para el técnico","Arrancas las plantas hoy","Aplicas el producto a todo el lote"],"correcta":0,"explica":"Un amarillamiento puede tener muchas causas; la foto de una hoja no alcanza."},{"p":"¿Qué información ayuda más al técnico?","ops":["Solo la foto","La respuesta de la aplicación","Fotos de planta completa y del lote, distribución, % afectado, fechas, riegos y aplicaciones previas"],"correcta":2,"explica":"El patrón en el lote y la historia de manejo orientan el diagnóstico."},{"p":"Mientras llega el técnico…","ops":["No haces nada","Marcas las plantas afectadas, registras el avance y evitas aplicar sin recomendación","Aplicas algo preventivo"],"correcta":1,"explica":"Documentar el avance sirve para decidir; aplicar a ciegas puede empeorar el problema."}]},{"tipo":"comparar","titulo":"Mensaje al técnico","malTitulo":"Sin datos","mal":"«Ingeniero, la app dice que es virus, ¿qué le echo?»","bienTitulo":"Completo","bien":"«Ingeniero: chile, 45 días después del trasplante. Hojas nuevas amarillentas en manchones del lado norte, 10% de plantas. Riego ayer; última aplicación hace 12 días. Le mando fotos de plantas y del lote. ¿Cuándo puede venir?»"},{"tipo":"reflexion","rotulo":"Tu contacto técnico","pregunta":"Escribe a quién acudes cuando aparece un problema sanitario (técnico, agrónomo, junta local o comité de sanidad) y qué información le mandarás siempre.","ayuda":"Contacto: … / Le mando: fotos de…, fechas de…"},{"tipo":"clave","items":["Describe: qué, dónde, desde cuándo, cuánto y qué se aplicó antes.","La IA arma el reporte; el técnico diagnostica.","Fotos y fechas en cada monitoreo."]}],"c-ia-campo-m2-l3":[{"tipo":"texto","texto":"El riego suele pagarse «cuando toca» y por eso casi nadie sabe cuánto cuesta por hectárea. Con dos o tres datos que ya tienes —horas de bombeo, consumo del motor y el precio que tú pagas— sale el número. Y ese número es el que te dice si conviene cambiar la forma de regar o los horarios."},{"tipo":"excel","rotulo":"Costo del riego","datos":[["Concepto","Valor"],["Horas de bombeo al mes",180],["Litros de diésel por hora",6],["Precio del diésel ($/L)",25.5],["Costo de diésel al mes",""],["Hectáreas regadas",6],["Costo de riego por hectárea al mes",""],["Costo del ciclo (4 meses)",""]],"retos":[{"celda":"B5","formula":"=B2*B3*B4","esperado":27540,"texto":"<b>B5</b>: costo de diésel al mes = horas × litros por hora × precio."},{"celda":"B7","formula":"=B5/B6","esperado":4590,"texto":"<b>B7</b>: costo de riego por hectárea al mes."},{"celda":"B8","formula":"=B5*4","esperado":110160,"texto":"<b>B8</b>: costo del riego en los 4 meses del ciclo.","explica":"$110,160 de riego en el ciclo, $4,590 por hectárea al mes. Usa tus propios datos: las horas de tu bitácora, el consumo real de tu motor medido con el tanque y el precio del último ticket. Con esos números ya puedes comparar si te conviene regar en otro horario o revisar fugas."}]},{"tipo":"plantilla","rotulo":"Bitácora de riego","texto":"Diséñame una bitácora de riego sencilla para llenar en el celular: fecha, lote, hectáreas regadas, hora de inicio y fin, horas totales, fuente de agua, consumo de combustible o energía, incidencias (fallas de bomba, fugas, baja presión) y observación del estado del cultivo. Agrega una hoja de resumen mensual que sume horas y costo por lote, y una lista de 6 revisiones de mantenimiento que debo hacerle al equipo de bombeo durante el ciclo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Los litros por hora que consume tu motor los sacas de…","ops":["Medirlo tú con el tanque en una jornada","Lo que diga la IA","Una tabla de internet"],"correcta":0},{"p":"Costo de riego por hectárea =","ops":["Costo total del riego ÷ hectáreas regadas","Hectáreas ÷ costo","Horas × hectáreas"],"correcta":0},{"p":"Una fuga o una bomba mal ajustada…","ops":["Se ve como horas de bombeo que suben sin explicación","No afecta el costo","Solo afecta si el agua es de pozo"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu riego","pregunta":"¿Cuántas horas riegas al mes y cuánto pagas de energía o combustible? Escribe los dos números aunque sean aproximados.","ayuda":"Horas al mes ≈ … / Pago al mes ≈ $…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de nogal en Chihuahua bombea con motor eléctrico. Pidió a la IA un programa de riego y le respondió «riega 2 horas diarias» sin preguntar el cultivo, el suelo, el gasto de la bomba ni la etapa. También le dijo cuánto cuesta el kilowatt-hora «en tarifa agrícola»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"«Riega 2 horas diarias»…","ops":["Es una buena regla","No se basa en nada de tu huerta: el programa se define con tu técnico y tus datos","Se usa en temporada de calor"],"correcta":1,"explica":"La necesidad de agua depende del cultivo, la etapa, el suelo y el clima."},{"p":"El costo del kilowatt-hora que dio la IA…","ops":["Se sustituye por el de tu recibo de luz","Se usa como referencia","Es el mismo para todos"],"correcta":0,"explica":"Tu tarifa y tus cargos están en tu recibo."},{"p":"¿Qué dato de tu bitácora de riego ayuda más a detectar fallas?","ops":["El nombre del regador","El color del agua","Horas de bombeo por lote comparadas semana contra semana"],"correcta":2,"explica":"Si las horas suben sin razón, hay fuga, falla o cambio en el pozo."}]},{"tipo":"relacionar","rotulo":"Dato del riego y su fuente","pares":[["Necesidad de agua del cultivo","Técnico con datos de tu huerta"],["Costo de la energía","Tu recibo de luz"],["Horas de bombeo","Tu bitácora de riego"],["Consumo del motor","Medición en campo"]]},{"tipo":"clave","items":["Costo del riego = horas × consumo × precio que tú pagas.","El consumo del motor se mide, no se supone.","Horas que suben sin razón: busca fuga o falla de bomba."]}],"c-ia-campo-m3-l1":[{"tipo":"texto","texto":"Al final del ciclo todo se resume en una pregunta: ¿cuánto sacaste por hectárea? Ese número, el <b>rendimiento</b>, es lo que permite comparar lotes, variedades y formas de manejo. Si solo registras la producción total, no puedes comparar nada, porque los lotes son de distinto tamaño."},{"tipo":"excel","rotulo":"Rendimiento por lote","datos":[["Lote","Hectáreas","Producción (t)","Rendimiento (t/ha)"],["Lote 1",4,26,""],["Lote 2",6,33,""],["Lote 3",3,21,""],["Promedio","","",""]],"retos":[{"celda":"D2","formula":"=C2/B2","esperado":6.5,"texto":"<b>D2</b>: rendimiento del lote 1 = producción ÷ hectáreas."},{"celda":"D3","formula":"=C3/B3","esperado":5.5,"texto":"<b>D3</b>: rendimiento del lote 2."},{"celda":"D4","formula":"=C4/B4","esperado":7,"texto":"<b>D4</b>: rendimiento del lote 3."},{"celda":"D5","formula":"=PROMEDIO(D2:D4)","esperado":6.333333333333333,"requiere":"PROMEDIO(","texto":"<b>D5</b>: promedio de los tres lotes.","explica":"El lote 3 rindió 7 t/ha y el lote 2 solo 5.5, casi 27% menos. Ahí es donde tu bitácora vale oro: ¿qué se hizo distinto en el lote 3? ¿riego, fecha de siembra, fertilización, suelo? Esa comparación es la que mejora el ciclo siguiente."}]},{"tipo":"plantilla","rotulo":"Comparar lotes con tu bitácora","texto":"Tengo estos rendimientos por lote, ya calculados: [pega lote, hectáreas, producción y rendimiento]. Y este es el manejo que le di a cada uno según mi bitácora: [pega fechas de siembra, riegos, fertilizaciones, variedad, tipo de suelo, incidencias]. Compáralos y dime qué diferencias de manejo coinciden con los lotes de mayor rendimiento. Distingue claramente lo que es coincidencia observada de lo que sería una conclusión comprobada, y dime qué tendría que probar el próximo ciclo para confirmarlo. No inventes datos ni rendimientos de referencia."},{"tipo":"destacado","texto":"<b>Una coincidencia no es una causa.</b> Que el lote que regaste más haya rendido más no prueba que fue por el riego: pudo ser el suelo, la variedad o la fecha de siembra. Lo que sí puedes hacer es anotar la hipótesis y probarla el próximo ciclo dejando una franja de comparación. Así se aprende con números y no con corazonadas."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Rendimiento por hectárea =","ops":["Producción del lote ÷ hectáreas del lote","Hectáreas ÷ producción","Producción × hectáreas"],"correcta":0},{"p":"Para comparar dos lotes de distinto tamaño usas…","ops":["El rendimiento por hectárea","La producción total","El número de costales de semilla"],"correcta":0},{"p":"El lote que más regaste rindió más. Eso…","ops":["Es una hipótesis que hay que probar el próximo ciclo","Prueba que el riego fue la causa","Significa que hay que regar el doble en todos"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de frijol en Zacatecas le pidió a la IA comparar su rendimiento con «el promedio del estado». La IA escribió: «El promedio estatal es de 1.8 t/ha; estás por encima». No citó fuente ni año, y el productor ya lo iba a poner en una solicitud de apoyo."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"El «promedio estatal» de la IA…","ops":["Se usa porque suena lógico","Se redondea","No se usa hasta verificarlo en la estadística oficial, con año y tipo de cultivo (riego o temporal)"],"correcta":2,"explica":"Las estadísticas agrícolas oficiales se publican por cultivo, ciclo, modalidad y año; un número sin fuente no se cita."},{"p":"Para una solicitud de apoyo, tus rendimientos…","ops":["Salen de tus registros de cosecha y ventas","Se pueden estimar con la IA","Se ponen altos para calificar"],"correcta":0,"explica":"Lo que declaras debe poder comprobarse con tus boletas, notas o facturas."},{"p":"¿Qué sí puede hacer la IA con tus rendimientos?","ops":["Inventar un promedio de comparación","Ordenar tus datos por lote y ciclo y preparar la tabla para la solicitud","Subirlos a internet"],"correcta":1,"explica":"Ordenar y presentar tus datos, sí; agregar cifras externas sin fuente, no."}]},{"tipo":"completar","rotulo":"Cifras con fuente","items":[{"frase":"Un promedio estatal se cita con fuente y ___.","resp":["año","fecha"]},{"frase":"El rendimiento se compara con el mismo cultivo y la misma ___ (riego o temporal).","resp":["modalidad"]},{"frase":"Lo que declaras se comprueba con boletas, notas o ___.","resp":["facturas","factura"]}]},{"tipo":"clave","items":["Rendimiento = producción ÷ hectáreas.","Compara lotes contra tu bitácora de manejo.","Coincidencia no es causa: prueba con una franja de comparación."]}],"c-ia-campo-m3-l2":[{"tipo":"texto","texto":"La oferta más alta no siempre es la que más te deja. Un comprador te ofrece más por tonelada pero descuenta por humedad e impurezas, paga a 45 días y no pone el flete; otro ofrece menos pero paga de contado en el campo. Para decidir necesitas comparar el <b>precio neto en tu bolsillo</b>, no el precio de pizarra."},{"tipo":"excel","rotulo":"Tu margen por hectárea","datos":[["Concepto","Valor"],["Rendimiento (t/ha)",6.5],["Precio por tonelada ($)",5200],["Ingreso por hectárea",""],["Costo por hectárea",24500],["Utilidad por hectárea",""],["Margen",""]],"retos":[{"celda":"B4","formula":"=B2*B3","esperado":33800,"texto":"<b>B4</b>: ingreso por hectárea = rendimiento × precio."},{"celda":"B6","formula":"=B4-B5","esperado":9300,"texto":"<b>B6</b>: utilidad por hectárea = ingreso − costo."},{"celda":"B7","formula":"=B6/B4","esperado":0.27514792899408286,"texto":"<b>B7</b>: margen = utilidad ÷ ingreso.","explica":"27.5% de margen con esos supuestos. Ahora juega: baja el precio a $4,600 por tonelada y verás que la utilidad se cae a $4,400 por hectárea. Por eso el precio al que cierras y el rendimiento pesan tanto: unos cuantos pesos por tonelada cambian todo el ciclo."}]},{"tipo":"plantilla","rotulo":"Comparar ofertas de compradores","texto":"Tengo estas ofertas por mi cosecha de [producto], [toneladas] toneladas: [para cada comprador anota precio por tonelada, descuentos que aplica por humedad o impurezas, quién paga el flete y cuánto cuesta, costo de maniobras y empaque, plazo de pago en días, anticipo si lo hay, y si ya me ha quedado mal antes]. Arma una tabla comparativa que calcule el neto que recibo por tonelada con todos los descuentos y costos, y otra columna con el plazo de pago. Dime qué preguntas debo hacerle a cada comprador antes de cerrar y qué señales de riesgo ves. No inventes precios de mercado ni supongas descuentos que no te di."},{"tipo":"destacado","texto":"<b>La IA no sabe a cómo está el producto hoy.</b> No tiene el precio de tu región, ni el de esta semana, ni el de tu calidad. Los precios los consultas con tus compradores, con otros productores de tu zona y con las fuentes de información de mercado que sigas. Lo que sí hace la IA, y muy bien, es comparar las ofertas que <b>tú</b> le pegas y sacar el neto de cada una."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un comprador ofrece $200 más por tonelada pero el flete corre por tu cuenta y cuesta $350 por tonelada.","ops":["Te conviene menos: el neto es más bajo","Te conviene: el precio es mayor","Da igual, se compensa con el volumen"],"correcta":0},{"p":"Le preguntas a la IA a cómo está el precio esta semana en tu región.","ops":["No lo sabe: lo consulto con compradores y fuentes de mercado","Uso el número que me dé","Uso el precio del año pasado que me dé"],"correcta":0},{"p":"Un comprador paga más pero a 60 días y ya te quedó mal antes.","ops":["El riesgo de cobranza entra en la decisión","Solo cuenta el precio","Le vendes todo para que se comprometa"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un productor de limón en Colima cerró por WhatsApp la venta de 30 toneladas. Pidió a la IA un contrato sencillo de compraventa. El borrador trae precio y volumen, pero no dice la calidad o calibre aceptado, quién decide la merma o el rechazo, dónde se entrega ni la fecha de pago."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué falta que más pleitos causa?","ops":["El nombre del producto","La calidad aceptada y cómo se determinan merma y rechazo","El logotipo"],"correcta":1,"explica":"La mayoría de los descuentos se discuten en la báscula; si no está escrito, gana el comprador."},{"p":"La fecha de pago…","ops":["Se escribe con día concreto y forma de pago","Se deja en «a la brevedad»","No hace falta"],"correcta":0,"explica":"Un plazo concreto es lo que puedes reclamar."},{"p":"¿Quién revisa el borrador antes de firmar?","ops":["Nadie, es sencillo","Solo el comprador","Tú, y si el monto es importante, un abogado o tu organización de productores"],"correcta":2,"explica":"La IA redacta; tú decides y, si hay mucho en juego, alguien con experiencia legal lo revisa."}]},{"tipo":"comparar","titulo":"Cláusula de calidad","malTitulo":"Abierta","mal":"«El producto deberá ser de buena calidad.»","bienTitulo":"Medible","bien":"«Se acepta limón [calibre y características acordadas]. La merma y el rechazo se determinan en presencia de ambas partes en el punto de entrega, con registro fotográfico. El pago se hace por transferencia a más tardar el [fecha].»"},{"tipo":"reflexion","rotulo":"Tus condiciones de venta","pregunta":"Escribe las cinco condiciones que siempre pondrás por escrito al vender tu cosecha.","ayuda":"1. Calidad… 2. Merma y rechazo… 3. Entrega… 4. Pago… 5. …"},{"tipo":"clave","items":["Compara el neto por tonelada, no el precio de pizarra.","Flete, descuentos, maniobras y plazo cambian la decisión.","El precio del mercado lo traes tú; la IA compara."]}],"c-ia-campo-m3-l3":[{"tipo":"destacado","texto":"<b>El caso:</b> sembraste 13 hectáreas en tres lotes. Sacaste 80 toneladas en total, pero un lote rindió mucho menos que los otros y no sabes por qué. Gastaste alrededor de $318,000 en el ciclo, aunque no llevaste cuentas de todo y no anotaste ningún jornal de tu familia. Un comprador te ofreció $5,000 por tonelada con pago a 60 días y flete por tu cuenta; otro, $4,700 de contado en el campo. Cerraste con el primero. Ya te pagaron y sientes que no quedó nada."},{"tipo":"pasos","rotulo":"Resuélvelo con la IA, paso por paso","pasos":["<b>Saca tu costo real (M1 L3):</b> arma la hoja de costos del ciclo, mete la mano de obra familiar y la maquinaria propia, y divide entre las 13 hectáreas. Hasta aquí no puedes opinar de nada.","<b>Calcula el rendimiento por lote (M3 L1):</b> producción ÷ hectáreas de cada lote. Vas a ver de inmediato cuál lote se cayó y cuánto te costó esa caída.","<b>Busca la causa en la bitácora (M1 L1, M1 L2):</b> pega tus registros de riego, fertilización y monitoreo del lote bajo y pídele a la IA que te señale diferencias de manejo, marcando qué es coincidencia y qué habría que probar.","<b>Rehaz la venta en papel (M3 L2):</b> calcula el neto por tonelada de las dos ofertas restando flete, descuentos y el costo de esperar 60 días. Compara con lo que sí cobraste.","<b>Mide el margen (M3 L2):</b> ingreso por hectárea menos costo por hectárea. Ese número, no el total de la venta, es el que dice si el ciclo funcionó.","<b>Prepara el siguiente ciclo (M2 L1, M2 L3):</b> pídele a la IA un plan de registro para el año entrante: bitácora diaria, control de insumos, bitácora de riego y una franja de comparación en el lote que falló."]},{"tipo":"practica","rotulo":"Decisiones del caso","preguntas":[{"p":"No anotaste los jornales de tu familia. Eso hace que…","ops":["Tu costo por hectárea salga más bajo de lo real","No pase nada, no se pagaron","El rendimiento por hectárea suba"],"correcta":0},{"p":"Un lote rindió mucho menos. Lo primero es…","ops":["Comparar su manejo registrado contra el de los otros lotes","Cambiar de semilla el próximo año","Dejar de sembrar ese lote"],"correcta":0},{"p":"Para comparar las dos ofertas de compra hay que…","ops":["Sacar el neto por tonelada con flete, descuentos y plazo","Tomar el precio por tonelada más alto","Elegir al comprador que pague más rápido, sin calcular"],"correcta":0},{"p":"El número que dice si el ciclo funcionó es…","ops":["La utilidad y el margen por hectárea","El total vendido","Las toneladas totales cosechadas"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu próximo ciclo","pregunta":"Escribe tres registros que te comprometes a llevar el próximo ciclo y quién los va a anotar (tú, un hijo, el encargado).","ayuda":"Registro 1… lo anota… / Registro 2… / Registro 3…"},{"tipo":"destacado","texto":"<b>¡Terminaste el curso!</b> La IA no conoce tu suelo, no ve tus plantas, no sabe el clima de mañana ni el precio de esta semana. Lo que hace es ordenar lo que tú registras, ayudarte a comparar y escribir lo que te da flojera escribir. Quien decide sigue siendo el productor; la diferencia es que ahora decide con números propios."},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso continúa:</b> para el siguiente ciclo quieres pedir un crédito. Le pides a la IA que redacte la descripción de tu unidad de producción y escribe: «rendimientos promedio de 7.5 t/ha en todos los lotes, sin incidencias sanitarias y con mercado asegurado». Tus registros dicen otra cosa."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Los rendimientos de 7.5 t/ha en todos los lotes…","ops":["Se dejan para calificar","Se cambian por tus rendimientos reales por lote, con su soporte","Se quitan todos los números"],"correcta":1,"explica":"Declarar datos falsos en una solicitud de crédito te expone a rechazo y a problemas más serios."},{"p":"«Mercado asegurado»…","ops":["Solo se escribe si tienes un contrato o acuerdo que lo respalde","Siempre se pone","Se cambia por «mercado garantizado»"],"correcta":0,"explica":"Una afirmación así se respalda con documentos."},{"p":"¿Qué le pides a la IA en su lugar?","ops":["Que exagere un poco","Que busque los requisitos del crédito","Que redacte solo con los datos que le das y marque [SOPORTE] donde se necesite documento"],"correcta":2,"explica":"Así la solicitud es honesta y sabes qué documentos juntar."}]},{"tipo":"completar","rotulo":"Solicitud honesta","items":[{"frase":"Cada cifra de la solicitud lleva su ___.","resp":["soporte","documento","comprobante"]},{"frase":"Los requisitos del crédito se consultan con la ___.","resp":["institución","institucion","financiera"]},{"frase":"La IA redacta solo con los datos que tú le ___.","resp":["das","pegas","doy"]}]},{"tipo":"reflexion","rotulo":"Tu carpeta de soporte","pregunta":"Escribe qué documentos tienes hoy para comprobar tus rendimientos, costos y ventas del último ciclo, y cuáles te faltan.","ayuda":"Tengo: … / Me faltan: …"},{"tipo":"clave","titulo":"Tu kit del campo con IA","items":["Bitácora de labores, control de insumos y bitácora de riego llenadas desde el celular.","Costo por hectárea completo, rendimiento por lote y margen real.","Reportes para tu técnico y comparación de ofertas con el neto por tonelada."]}],"c-ia-campo-m4-l1":[{"tipo":"texto","texto":"Vender a exportación o a cadenas grandes exige registros impecables: qué se aplicó, cuándo, en qué lote, quién cosechó, de qué lote salió cada caja. Los compradores revisan que se respeten los <b>intervalos de seguridad</b> de la etiqueta y los <b>límites máximos de residuos</b> del país de destino, y muchas veces piden una certificación de inocuidad. La IA ayuda mucho a ordenar registros y preparar auditorías, pero <b>inventa con seguridad</b> límites de residuos, productos autorizados y requisitos de certificación. Esos datos salen de la etiqueta, del comprador, del organismo certificador y de las autoridades sanitarias, y los interpreta tu agrónomo."},{"tipo":"tabla","titulo":"Errores comunes de la IA en exportación","encabezados":["Error","Control"],"filas":[["Afirmar límites de residuos de un país","Fuente oficial del país destino y el comprador"],["Decir que un producto está autorizado para un cultivo","Etiqueta autorizada y agrónomo"],["Listar requisitos de una certificación","Documentos vigentes del organismo certificador"],["Calcular fechas de cosecha sin el intervalo de la etiqueta","Registro de aplicaciones y etiqueta de cada producto"]]},{"tipo":"excel","rotulo":"¿Ya se puede cosechar ese lote?","instruccion":"Días de práctica. El intervalo real viene en la etiqueta de cada producto y lo confirma tu agrónomo.","datos":[["Dato","Valor"],["Día del ciclo de la última aplicación",58],["Día del ciclo planeado para cosechar",63],["Días entre aplicación y cosecha",""],["Intervalo de seguridad de la etiqueta (días)",7],["¿Se puede cosechar ese día?",""]],"retos":[{"celda":"B4","formula":"=B3-B2","esperado":5,"texto":"<b>B4</b>: días entre la última aplicación y la cosecha planeada."},{"celda":"B6","formula":"=SI(B4>=B5,\"SI\",\"NO\")","esperado":"NO","requiere":"SI(","texto":"<b>B6</b>: escribe una fórmula con SI que diga «SI» cuando los días alcancen el intervalo y «NO» cuando no.","pista":"=SI(B4>=B5,…,…)","explica":"Faltan dos días: cosechar el día 63 rompería el intervalo de la etiqueta. Con tu registro de aplicaciones, este cálculo se hace por lote y por producto antes de programar la cosecha."}]},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"La IA te da el límite de residuos de un producto para exportar a otro país. Tú…","ops":["Lo confirmas con la fuente oficial del país destino, el comprador y tu agrónomo","Lo usas","Lo usas con un margen"],"correcta":0,"explica":"Los límites cambian por país, producto y cultivo, y se actualizan."},{"p":"Un auditor pide el historial de aplicaciones de un lote. Te sirve…","ops":["Tu memoria","Tu registro de aplicaciones con fecha, producto, dosis, lote y responsable","Un resumen que redacte la IA sin tus registros"],"correcta":1,"explica":"La trazabilidad se demuestra con registros hechos en el momento."},{"p":"¿Cómo te ayuda la IA a preparar una auditoría?","ops":["Inventando registros faltantes","Diciéndote que ya cumples","Revisando tus registros contra la lista del certificador para encontrar huecos"],"correcta":2,"explica":"Encontrar huecos antes de la auditoría, sí; rellenarlos con datos inventados, jamás."}]},{"tipo":"relacionar","rotulo":"Dato y quién lo confirma","pares":[["Cultivos y dosis autorizados","Etiqueta y agrónomo"],["Límites de residuos del destino","Fuente oficial del país y comprador"],["Requisitos de certificación","Organismo certificador"],["Historial de aplicaciones","Tus registros de campo"]]},{"tipo":"plantilla","rotulo":"Registro de trazabilidad por lote","texto":"Diséñame un registro de trazabilidad para [cultivo] en [número] lotes, llenable desde el celular: por lote, aplicaciones (fecha, producto como viene en etiqueta, dosis, responsable, intervalo de seguridad según etiqueta, fecha más próxima permitida para cosechar), cosechas (fecha, cuadrilla, cajas o kilos, destino) y una columna de verificación. Agrega una hoja que revise que ninguna cosecha quede antes de la fecha permitida. No propongas productos, dosis ni intervalos: déjalos en blanco para llenarlos con la etiqueta.","nota":"Cópiala y adáptala."},{"tipo":"clave","items":["Intervalos y dosis: de la etiqueta y el agrónomo.","Límites de residuos y certificación: de las fuentes oficiales y el comprador.","La IA ordena y revisa huecos; nunca rellena registros."]}],"c-ia-campo-m4-l2":[{"tipo":"texto","texto":"En ganadería también se decide con números: cuántos animales tienes, cuánto pesan, cuánto ganan por día, cuánto te cuesta alimentarlos. La IA te ayuda a pasar tus notas de pesaje a una tabla, a calcular la <b>ganancia diaria de peso</b> y a preparar tus registros de identificación y movilización. Lo que <b>no</b> hace es diagnosticar ni recetar: vacunas, desparasitantes, antibióticos, dosis y tiempos de retiro antes de vender leche o carne los define el médico veterinario con la etiqueta del producto. Un animal enfermo se atiende con el veterinario, no con un chat."},{"tipo":"excel","rotulo":"Ganancia diaria de peso","instruccion":"Pesos de práctica. Usa los de tu báscula.","datos":[["Dato","Valor"],["Peso al inicio (kg)",280],["Peso al final (kg)",352],["Días entre pesajes",60],["Kilos ganados",""],["Ganancia diaria (kg/día)",""]],"retos":[{"celda":"B5","formula":"=B3-B2","esperado":72,"texto":"<b>B5</b>: kilos ganados = peso final − peso inicial."},{"celda":"B6","formula":"=B5/B4","esperado":1.2,"texto":"<b>B6</b>: ganancia diaria = kilos ganados ÷ días.","explica":"1.2 kg por día. Si comparas este dato entre lotes o entre dietas, sabes qué manejo rinde más; si un animal gana mucho menos que el resto, es señal para que lo revise el veterinario."}]},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"Un becerro está decaído y la IA sugiere un antibiótico y una dosis. Tú…","ops":["Lo aplicas","Llamas al veterinario; la IA no receta","Aplicas media dosis"],"correcta":1,"explica":"Un medicamento mal elegido o mal dosificado pone en riesgo al animal y deja residuos en leche o carne."},{"p":"Los tiempos de retiro antes de vender leche o carne salen de…","ops":["La etiqueta del medicamento y el veterinario","La IA","La costumbre del rancho"],"correcta":0,"explica":"Cada producto indica su tiempo de retiro; vender antes puede causar rechazo y riesgos a la salud."},{"p":"¿Para qué te sirve la IA en tus registros de hato?","ops":["Para diagnosticar","Para decidir qué vender","Para ordenar pesajes, identificación, partos y tratamientos que indicó el veterinario"],"correcta":2,"explica":"Registrar bien es donde la IA ahorra más tiempo."}]},{"tipo":"comparar","titulo":"Pedir ayuda sobre un animal enfermo","malTitulo":"Peligroso","mal":"«Mi vaca tiene fiebre y no come, ¿qué le inyecto?»","bienTitulo":"Útil","bien":"«Ayúdame a ordenar lo que le voy a decir al veterinario: animal, arete, edad, síntomas, desde cuándo, qué come, tratamientos previos con fecha.»"},{"tipo":"plantilla","rotulo":"Registro de hato","texto":"Diséñame un registro de hato para [número] cabezas de [tipo: engorda, cría, leche], llenable desde el celular: identificación (arete oficial y número interno), sexo, fecha de nacimiento o ingreso, pesajes con fecha, ganancia diaria calculada, partos, tratamientos indicados por el veterinario (fecha, producto, quién lo indicó, fin del tiempo de retiro) y movilizaciones. Agrega un resumen por lote. No propongas medicamentos, dosis ni calendarios de vacunación: déjalos en blanco para que los indique el veterinario.","nota":"Cópiala y adáptala."},{"tipo":"clave","items":["Ganancia diaria = kilos ganados ÷ días.","Diagnóstico, medicamentos y retiros: del veterinario y la etiqueta.","La IA ordena registros; no receta."]}],"c-ia-campo-m4-l3":[{"tipo":"texto","texto":"El crédito de avío, el seguro agrícola o ganadero y los programas de apoyo pueden salvar un ciclo, pero cada institución tiene sus requisitos, fechas y condiciones, y <b>los programas públicos cambian de un año a otro</b>. La IA suele dar requisitos, montos y fechas de ventanilla que ya no existen o que nunca existieron. Úsala para ordenar tu carpeta, redactar la descripción de tu unidad con tus datos reales y calcular el costo del crédito con las condiciones que te den por escrito; los requisitos y las cifras oficiales los confirmas directamente con la institución, la financiera o la aseguradora."},{"tipo":"excel","rotulo":"Lo que te cuesta el crédito de avío","instruccion":"Condiciones de práctica. Usa la tasa y el plazo de tu contrato; pregunta además por comisiones y seguros.","datos":[["Dato","Valor"],["Monto del crédito ($)",200000],["Tasa de interés anual",0.14],["Meses del crédito",6],["Intereses del ciclo",""],["Hectáreas financiadas",10],["Costo del crédito por hectárea",""]],"retos":[{"celda":"B5","formula":"=B2*B3*B4/12","esperado":14000,"texto":"<b>B5</b>: intereses = monto × tasa anual × meses ÷ 12."},{"celda":"B7","formula":"=B5/B6","esperado":1400,"texto":"<b>B7</b>: costo del crédito por hectárea.","explica":"$1,400 por hectárea que van a tu hoja de costos. Es un cálculo simple de interés; tu contrato puede tener comisiones, seguros o una forma de cálculo distinta: pide el costo total por escrito."}]},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"La IA te lista los requisitos de un programa de apoyo de este año. Tú…","ops":["Los das por buenos","Los confirmas en la convocatoria oficial vigente o en la ventanilla","Los usas si coinciden con los del año pasado"],"correcta":1,"explica":"Las reglas de los programas cambian cada año."},{"p":"Para comparar dos créditos, usas…","ops":["El costo total por escrito de cada uno: tasa, comisiones, seguros y plazo","La tasa que recuerda la IA","El que te den más rápido"],"correcta":0,"explica":"Una tasa baja con comisiones altas puede salir más cara."},{"p":"¿Qué te conviene pedirle a la IA para tu solicitud?","ops":["Que calcule si te aprueban","Que mejore tus números","Que ordene tu carpeta y marque qué documento soporta cada dato"],"correcta":2,"explica":"Una carpeta completa y honesta acelera el trámite."}]},{"tipo":"completar","rotulo":"Dinero con papeles","items":[{"frase":"Intereses = monto × tasa anual × meses ÷ ___.","resp":["12","doce"]},{"frase":"Los requisitos de un programa se confirman en la ___ vigente.","resp":["convocatoria","ventanilla"]},{"frase":"El costo del crédito se agrega a tu hoja de ___.","resp":["costos","costo"]}]},{"tipo":"reflexion","rotulo":"Tu financiamiento","pregunta":"Escribe con quién financias o aseguras tu producción, qué condiciones tienes por escrito y qué dato te falta preguntar.","ayuda":"Institución: … / Tengo por escrito: … / Me falta preguntar: …"},{"tipo":"plantilla","rotulo":"Carpeta de solicitud","texto":"Voy a solicitar [crédito de avío / seguro / apoyo] para [cultivo o ganado] en [superficie o cabezas] en [municipio]. Arma una lista de verificación de mi carpeta con: documentos de identidad y de la tierra o el hato que suelen pedir, registros de producción y ventas de ciclos anteriores, costos del ciclo, y preguntas que debo hacer a la institución. Para cada punto indica [CONFIRMAR CON LA INSTITUCIÓN]. Redacta además una descripción de mi unidad solo con estos datos reales: [pega tus datos]. No inventes requisitos, montos, tasas ni fechas.","nota":"Cópiala y adáptala."},{"tipo":"clave","items":["Requisitos y fechas: en la convocatoria vigente o la institución.","Intereses = monto × tasa × meses ÷ 12, más comisiones por escrito.","Solicitud con datos reales y soporte."]}],"c-ia-campo-m5-l1":[{"tipo":"texto","texto":"Administras una unidad de 20 hectáreas de hortalizas en el Bajío. Durante el día usas un asistente de IA en cada tarea y en cada escena hay por lo menos un error plantado. Encuéntralo, di qué harías y escribe tu respuesta antes de pasar a la siguiente."},{"tipo":"texto","texto":"<b>Escena 1 — 6:30 a.m.</b> Dictaste tus notas de ayer. En la bitácora que armó la IA dice: «Lote 3: aplicación de fungicida, 2 L/ha». Tu nota decía «el lote 3 lo aplicamos el jueves, ya está el producto», y nunca dijiste la dosis."},{"tipo":"reflexion","rotulo":"Escena 1","pregunta":"Escribe qué corriges en la bitácora y qué instrucción agregas al prompt.","ayuda":"Corrijo… / Agrego: «…»"},{"tipo":"texto","texto":"<b>Escena 2 — 9:00 a.m.</b> Aparecieron manchas en las hojas del lote 1. Le preguntaste a la IA y te respondió el nombre de una enfermedad, una mezcla de dos productos con dosis y «puedes cosechar en 3 días»."},{"tipo":"reflexion","rotulo":"Escena 2","pregunta":"Enumera lo que no debes tomar de esa respuesta y escribe qué harás en su lugar y a quién llamas.","ayuda":"No tomo: … / En su lugar: reporte con… / Llamo a…"},{"tipo":"texto","texto":"<b>Escena 3 — 1:00 p.m.</b> Planeas la cosecha y la venta. Sin pegarle datos, le preguntaste a la IA si lloverá esta semana y a cómo está el producto. Contestó: «No se esperan lluvias; el precio en tu región está en $6,200 por tonelada»."},{"tipo":"reflexion","rotulo":"Escena 3","pregunta":"Escribe de dónde sacarás el pronóstico y el precio, y cómo usarás después a la IA con esos datos.","ayuda":"Pronóstico de… / Precio con… / Luego le pego a la IA…"},{"tipo":"texto","texto":"<b>Escena 4 — 6:00 p.m.</b> Preparas una solicitud de crédito. Subiste a un asistente público fotos de tu INE, tu CURP, el título de la parcela y tu estado de cuenta. El borrador dice «rendimiento promedio de 45 t/ha» aunque tus boletas del último ciclo dan 32."},{"tipo":"reflexion","rotulo":"Escena 4","pregunta":"Identifica los dos problemas (de datos personales y de contenido) y escribe qué harás distinto desde mañana.","ayuda":"Datos: … / Contenido: … / Desde mañana…"},{"tipo":"practica","rotulo":"Revisión del día","preguntas":[{"p":"En la escena 2, ¿qué parte es más peligrosa?","ops":["El nombre de la enfermedad","La mezcla con dosis y el «puedes cosechar en 3 días»","Que mencionó el lote"],"correcta":1,"explica":"Dosis, mezclas e intervalos vienen de la etiqueta y el agrónomo; seguir a la IA puede dañar el cultivo o causar rechazo por residuos."},{"p":"En la escena 4, ¿qué no debió subirse a un asistente público?","ops":["INE, CURP, título de la parcela y estado de cuenta","El nombre del cultivo","El número de hectáreas"],"correcta":0,"explica":"Documentos de identidad, propiedad y bancarios no van a herramientas públicas."},{"p":"En la escena 1, la dosis «2 L/ha»…","ops":["Se deja porque es la común","Se cambia por la de la etiqueta","Se borra: la aplicación aún no ocurre y la dosis no la dictaste"],"correcta":2,"explica":"La IA registró como hecha una labor planeada y además inventó la dosis."},{"p":"¿Qué tienen en común los cuatro errores?","ops":["La IA completó o supuso datos que nadie verificó","Se usó un celular viejo","Faltó rapidez"],"correcta":0,"explica":"La defensa siempre es la misma: tus registros, la etiqueta, el técnico y las fuentes oficiales."}]},{"tipo":"clave","items":["Bitácora: separa lo planeado de lo realizado.","Dosis, mezclas e intervalos: etiqueta y agrónomo, nunca la IA.","Documentos personales y bancarios, jamás en herramientas públicas."]}],"c-ia-campo-m5-l2":[{"tipo":"texto","texto":"Terminas armando tu propio kit con tu parcela, tu huerta o tu rancho. La idea es que el próximo ciclo lo uses desde el primer día y que cualquiera de tu equipo pueda seguirlo."},{"tipo":"reflexion","rotulo":"1. Tu biblioteca de prompts","pregunta":"Elige los cinco prompts del curso que más usarás (bitácora, aplicaciones, costos, plan con pronóstico, reporte al técnico, riego, rendimiento, ofertas, trazabilidad, hato, carpeta de crédito) y adáptalos. Escribe el título de cada uno y la instrucción anti-inventos que agregaste.","ayuda":"1. Bitácora desde nota de voz — agregué: «…» 2. …"},{"tipo":"reflexion","rotulo":"2. Tu política de datos","pregunta":"Escribe en cinco reglas qué información nunca subes a herramientas públicas (identificaciones, títulos, cuentas, datos de trabajadores y compradores) y cómo la sustituyes.","ayuda":"1. INE y CURP → nunca. 2. Nombres de compradores → [COMPRADOR A]. 3. …"},{"tipo":"reflexion","rotulo":"3. Tu lista de verificación","pregunta":"Escribe la lista que aplicarás a todo lo que produzca la IA antes de usarlo: cantidades y dosis, fechas, clima, precios, cifras oficiales y promesas en documentos.","ayuda":"☐ Dosis e intervalos contra etiqueta ☐ Pronóstico de fuente oficial ☐ …"},{"tipo":"reflexion","rotulo":"4. Tu entregable real","pregunta":"Produce con IA un entregable real (bitácora de la semana, hoja de costos, comparación de ofertas, registro de hato o carpeta de crédito), revísalo con tu lista y escribe qué corregiste y cuánto tiempo te ahorró.","ayuda":"Entregable: … / Corregí: 1) … 2) … / Tiempo ahorrado: …"},{"tipo":"plantilla","rotulo":"Índice de tu kit","texto":"KIT DEL CAMPO CON IA — [nombre de la unidad de producción]\n1. Biblioteca de prompts: [bitácora] [aplicaciones] [costos] [plan con pronóstico] [reporte al técnico] [riego] [rendimiento] [ofertas] [trazabilidad] [hato] [carpeta de crédito]\n2. Política de datos: [qué nunca se sube] [cómo se anonimiza] [quién revisa]\n3. Lista de verificación: [dosis e intervalos según etiqueta] [pronóstico oficial] [precios de compradores] [cifras con fuente] [solicitudes con soporte]\n4. Límites: [recetas y diagnósticos → agrónomo o técnico] [animales → veterinario] [requisitos → institución]\n5. Entregable de muestra: [archivo] [fecha] [qué se corrigió]\nÚltima actualización: [fecha]","nota":"Cópiala y adáptala."},{"tipo":"clave","items":["Tu kit se usa desde el primer día del ciclo.","La etiqueta, el técnico y las fuentes oficiales mandan sobre la IA.","Las decisiones y la responsabilidad son del productor."]}]},"q":{"c-ia-campo-m1":[{"p":"La bitácora de campo se llena mejor…","ops":["Con nota de voz en el momento y orden en la noche","De memoria cada mes","Al terminar el ciclo","No se llena"],"correcta":0},{"p":"Si la IA completa un dato que no dictaste…","ops":["Se borra y se deja en blanco","Se acepta","Se publica","Se duplica"],"correcta":0},{"p":"La superficie del lote se registra en…","ops":["Hectáreas","Litros","Toneladas","Jornales"],"correcta":0},{"p":"Qué producto y qué dosis aplicar lo define…","ops":["La etiqueta y un técnico con responsiva","La IA","El vecino","El comprador"],"correcta":0},{"p":"Registrar las hectáreas tratadas permite…","ops":["Saber el consumo de insumo por hectárea","Nada","Bajar el precio","Evitar el riego"],"correcta":0},{"p":"Costo por hectárea =","ops":["Costo total del ciclo ÷ hectáreas","Hectáreas ÷ costo total","Costo total × hectáreas","Precio de venta ÷ costo"],"correcta":0},{"p":"No contar la mano de obra familiar hace que el costo…","ops":["Salga falsamente bajo","Suba","No cambie","Desaparezca"],"correcta":0},{"p":"El insumo que representa el mayor porcentaje del costo…","ops":["Es el primero donde conviene negociar","Se ignora","Se compra de más","No se revisa"],"correcta":0}],"c-ia-campo-m2":[{"p":"El pronóstico del clima lo consultas en…","ops":["La fuente oficial y tu estación cercana","La IA","El almanaque","Nadie"],"correcta":0},{"p":"Pegarle el pronóstico a la IA sirve para…","ops":["Que te ayude a acomodar las labores","Que prediga el clima","Que riegue","Nada"],"correcta":0},{"p":"El plan de labores que devuelve la IA…","ops":["Se valida con lo que ves en campo","Se ejecuta sin revisar","Se descarta","Se imprime"],"correcta":0},{"p":"Ante un problema sanitario, la IA sirve para…","ops":["Armar el reporte de lo que observas","Diagnosticar","Recetar producto","Firmar la responsiva"],"correcta":0},{"p":"Quien diagnostica y recomienda es…","ops":["Un técnico o ingeniero agrónomo","La IA","El proveedor de insumos por teléfono","El comprador"],"correcta":0},{"p":"Anotar el porcentaje de plantas afectadas permite…","ops":["Saber si el problema avanza o se detuvo","Vender mejor","Regar menos","Nada"],"correcta":0},{"p":"Costo del riego al mes =","ops":["Horas × consumo por hora × precio","Horas ÷ hectáreas","Hectáreas × precio","Litros ÷ horas"],"correcta":0},{"p":"El consumo por hora de tu motor…","ops":["Se mide en campo con el tanque","Lo da la IA","Viene en la factura del agua","No se puede saber"],"correcta":0}],"c-ia-campo-m3":[{"p":"Rendimiento por hectárea =","ops":["Producción ÷ hectáreas","Hectáreas ÷ producción","Producción × precio","Costo ÷ producción"],"correcta":0},{"p":"Para comparar lotes de distinto tamaño se usa…","ops":["El rendimiento por hectárea","La producción total","El número de jornales","El color de la planta"],"correcta":0},{"p":"Que el lote más regado haya rendido más…","ops":["Es una hipótesis por probar","Es una causa comprobada","No significa nada","Se ignora"],"correcta":0},{"p":"Al comparar compradores se decide por…","ops":["El neto por tonelada y el plazo de pago","El precio de pizarra","Quién llama primero","La cercanía"],"correcta":0},{"p":"El precio del producto de esta semana lo sabe…","ops":["Tu comprador y las fuentes de mercado que sigas","La IA","El técnico","Nadie"],"correcta":0},{"p":"Margen =","ops":["Utilidad ÷ ingreso","Ingreso ÷ costo","Costo × utilidad","Precio × rendimiento"],"correcta":0},{"p":"No registrar la mano de obra familiar…","ops":["Hace que el costo parezca más bajo","Sube el rendimiento","Mejora la venta","No cambia nada"],"correcta":0},{"p":"En el campo, la IA sirve sobre todo para…","ops":["Ordenar registros, comparar y redactar; tú decides","Diagnosticar plagas","Fijar precios","Predecir el clima"],"correcta":0}],"c-ia-campo-m4":[{"p":"El intervalo de seguridad antes de cosechar se toma de…","ops":["La IA","La etiqueta del producto y el agrónomo","El comprador","La costumbre"],"correcta":1},{"p":"Si faltan días para cumplir el intervalo de la etiqueta…","ops":["Se cosecha igual","Se lava el producto","Se reprograma la cosecha de ese lote","Se vende a otro comprador"],"correcta":2},{"p":"Los límites de residuos del país destino se confirman con…","ops":["La fuente oficial de ese país y el comprador","La IA","Un foro","El vecino"],"correcta":0},{"p":"Ganancia diaria de peso =","ops":["Peso final × días","Días ÷ kilos ganados","Peso inicial ÷ días","Kilos ganados ÷ días"],"correcta":3},{"p":"Un animal enfermo se atiende con…","ops":["Lo que sugiera la IA","El médico veterinario","El producto más barato","Media dosis de antibiótico"],"correcta":1},{"p":"Los requisitos de un programa de apoyo se confirman en…","ops":["La convocatoria vigente o la ventanilla","La IA","La lista del año pasado","Redes sociales"],"correcta":0},{"p":"Intereses de un crédito simple =","ops":["Monto ÷ tasa","Monto + tasa × meses","Monto × tasa anual × meses ÷ 12","Tasa × meses"],"correcta":2}],"c-ia-campo-m5":[{"p":"La IA registra como hecha una aplicación que solo estaba planeada…","ops":["Se deja","Se corrige y se separa lo planeado de lo realizado","Se borra todo el día","Se registra con otra fecha"],"correcta":1},{"p":"Una mezcla de productos con dosis sugerida por la IA…","ops":["Se aplica","Se aplica a media dosis","Se prueba en un lote","No se usa: la recomendación es del agrónomo con la etiqueta"],"correcta":3},{"p":"El pronóstico y el precio de la semana los obtienes de…","ops":["La fuente oficial y tus compradores","La IA","El almanaque","El año pasado"],"correcta":0},{"p":"La INE y el estado de cuenta en un asistente público…","ops":["Están bien si es rápido","Se suben solo una vez","No se suben nunca","Se suben si es para un crédito"],"correcta":2},{"p":"En una solicitud de crédito, los rendimientos…","ops":["Se redondean hacia arriba","Salen de tus boletas y registros","Los estima la IA","Se copian del promedio estatal"],"correcta":1},{"p":"La lista de verificación se aplica…","ops":["A todo lo que produce la IA antes de usarlo","Solo a las ventas","Una vez por ciclo","Solo si hay auditoría"],"correcta":0},{"p":"Las decisiones de la unidad de producción son…","ops":["De la IA","Del comprador","Del proveedor de insumos","Del productor, con su técnico y sus registros"],"correcta":3}]}});
